INSERT INTO clinic_services (clinic_id, service_id, active)
SELECT clinics.id, services.id, true
FROM clinics
CROSS JOIN imported_skus
JOIN services ON services.sku = imported_skus.sku
WHERE clinics.active = true
ON CONFLICT (clinic_id, service_id) DO UPDATE SET active = true;
